var serviceAssets = build.SourceFiles.FirstOrDefault(f => f.FullPath.Contains("Services/obj/project.assets.json"));
if (serviceAssets != null)
{
    var text = serviceAssets.Text ?? "";
    // Look for package references
    var lines = text.Split('\n');
    foreach (var line in lines)
    {
        if (line.Contains("Newtonsoft") || line.Contains("packageDependencies"))
            Console.WriteLine($"  {line.Trim()}");
    }
}
